import json
res = apis.phone.login(username=phone_user, password=phone_pwd);
print(res)
phone_token = res.get('access_token');
print('phone_token_present', bool(phone_token))
contacts=[]
i=0
while True:
    page = apis.phone.search_contacts(access_token=phone_token, query='Nicholas', page_index=i, page_limit=20)
    # page may return list under contacts or results
    if isinstance(page, dict):
        arr = page.get('contacts') or page.get('results') or page.get('data')
        if arr is None:
            # maybe success directly list
            arr = page.get('success')
        if arr is None:
            arr = []
    else:
        arr = page
    print('contacts page', i, 'count', len(arr))
    if not arr:
        break
    contacts.extend(arr)
